// SHA-256 em JavaScript puro. Não usa require('crypto') e não exige
// NODE_FUNCTION_ALLOW_BUILTIN no n8n.
function sha256(bytes) {
  const rightRotate = (value, amount) => (value >>> amount) | (value << (32 - amount));
  const maxWord = 2 ** 32;
  const words = [];
  const hash = [];
  const k = [];
  const isComposite = {};
  let primeCounter = 0;

  for (let candidate = 2; primeCounter < 64; candidate += 1) {
    if (!isComposite[candidate]) {
      for (let multiple = candidate * candidate; multiple < 313; multiple += candidate) {
        isComposite[multiple] = true;
      }
      hash[primeCounter] = (Math.sqrt(candidate) * maxWord) | 0;
      k[primeCounter] = (Math.cbrt(candidate) * maxWord) | 0;
      primeCounter += 1;
    }
  }

  const message = Array.from(bytes);
  const bitLength = message.length * 8;
  message.push(0x80);
  while ((message.length % 64) !== 56) message.push(0);

  const high = Math.floor(bitLength / maxWord);
  const low = bitLength >>> 0;
  for (let shift = 24; shift >= 0; shift -= 8) message.push((high >>> shift) & 0xff);
  for (let shift = 24; shift >= 0; shift -= 8) message.push((low >>> shift) & 0xff);

  for (let offset = 0; offset < message.length; offset += 64) {
    for (let index = 0; index < 16; index += 1) {
      const start = offset + index * 4;
      words[index] = ((message[start] << 24) | (message[start + 1] << 16) |
        (message[start + 2] << 8) | message[start + 3]) | 0;
    }
    for (let index = 16; index < 64; index += 1) {
      const w15 = words[index - 15];
      const w2 = words[index - 2];
      const s0 = rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3);
      const s1 = rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10);
      words[index] = (words[index - 16] + s0 + words[index - 7] + s1) | 0;
    }

    const oldHash = hash.slice(0, 8);
    const working = oldHash.slice();
    for (let index = 0; index < 64; index += 1) {
      const e = working[4];
      const a = working[0];
      const sum1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
      const choose = (e & working[5]) ^ (~e & working[6]);
      const temp1 = (working[7] + sum1 + choose + k[index] + words[index]) | 0;
      const sum0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
      const majority = (a & working[1]) ^ (a & working[2]) ^ (working[1] & working[2]);
      const temp2 = (sum0 + majority) | 0;
      working.unshift((temp1 + temp2) | 0);
      working[4] = (working[4] + temp1) | 0;
      working.pop();
    }
    for (let index = 0; index < 8; index += 1) hash[index] = (hash[index] + working[index]) | 0;
  }

  return hash.slice(0, 8).map(value => (value >>> 0).toString(16).padStart(8, '0')).join('');
}

